:root { font-family: system-ui, sans-serif; color: #17263b; background: #f4f6fa; }
body { margin: 0; }
main { max-width: 760px; margin: 3rem auto; padding: 2rem; background: white; border-radius: 12px; box-shadow: 0 4px 24px #17263b12; }
h1 { margin-top: 0; overflow-wrap: anywhere; }
form { display: flex; flex-wrap: wrap; gap: .75rem; align-items: center; margin-bottom: 1rem; }
label { width: 100%; font-weight: 600; }
input { flex: 1; min-width: 120px; padding: .7rem; border: 1px solid #728096; border-radius: 5px; font: inherit; }
button { padding: .7rem 1rem; border: 0; border-radius: 5px; background: #2458b8; color: white; font: inherit; cursor: pointer; }
button:disabled { opacity: .6; cursor: wait; }
:focus-visible { outline: 3px solid #d18d00; outline-offset: 3px; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: 1rem 0; border-bottom: 1px solid #dce2eb; }
.project-row span { overflow-wrap: anywhere; min-width: 0; }
.project-row button { flex-shrink: 0; }
[role="alert"] { color: #a51d24; }
@media (max-width: 600px) { main { margin: 1rem; padding: 1rem; } }

